/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, computed, effect, input, output, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatButtonToggleModule } from '@angular/material/button-toggle';
import { MatTooltipModule } from '@angular/material/tooltip';
import { DisplayProvider } from '@shared/data/display-provider';
import { SelectionModel } from '@shared/data/selection-model';

export type CalendarMode = 'month' | 'week' | 'agenda';

export interface CalendarItemMapper<T> {
  start(item: T): Date;
  end(item: T): Date | null;
  title(item: T): string;
  color?(item: T): string;
  allDay?(item: T): boolean;
}

interface CalendarEvent {
  item: any;
  title: string;
  start: Date;
  end: Date;
  color: string;
  allDay: boolean;
  // week grid layout
  top: number;
  height: number;
  left: number;
  width: number;
}

interface MonthDay {
  date: Date;
  isCurrentMonth: boolean;
  isToday: boolean;
  events: CalendarEvent[];
}

interface WeekDay {
  date: Date;
  isToday: boolean;
  events: CalendarEvent[];
}

interface AgendaGroup {
  date: Date;
  label: string;
  events: CalendarEvent[];
}

const HOUR_PX = 64; // pixels per hour in week view
const DAY_NAMES = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const MONTH_NAMES = [
  'Enero',
  'Febrero',
  'Marzo',
  'Abril',
  'Mayo',
  'Junio',
  'Julio',
  'Agosto',
  'Septiembre',
  'Octubre',
  'Noviembre',
  'Diciembre',
];
const HOURS = Array.from({ length: 24 }, (_, i) => i);

function startOfDay(d: Date): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}
function addDays(d: Date, n: number): Date {
  const r = new Date(d);
  r.setDate(r.getDate() + n);
  return r;
}
function isSameDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}
function eventToMinutes(d: Date): number {
  return d.getHours() * 60 + d.getMinutes();
}
function overlaps(a: CalendarEvent, b: CalendarEvent): boolean {
  return a.start < b.end && a.end > b.start;
}

@Component({
  selector: 'calendar-view',
  standalone: true,
  imports: [
    CommonModule,
    MatButtonModule,
    MatIconModule,
    MatProgressBarModule,
    MatButtonToggleModule,
    MatTooltipModule,
  ],
  templateUrl: './calendar-view.component.html',
  styleUrls: ['./calendar-view.component.scss'],
})
export class CalendarViewComponent {
  data = input.required<any[] | undefined>();
  mapper = input.required<CalendarItemMapper<any>>();
  display = input<DisplayProvider<any>>();
  searching = input<boolean>();
  selectionModel = input<SelectionModel<any> | undefined>();
  initialMode = input<CalendarMode>('month');

  next = output<void>();
  activate = output<any>();
  periodChange = output<{ from: Date; to: Date }>();

  readonly mode = signal<CalendarMode>('month');
  readonly currentDate = signal<Date>(new Date());
  readonly today = new Date();
  readonly hours = HOURS;
  readonly hourPx = HOUR_PX;

  // ── Computed period label ────────────────────────────────────────────────
  periodLabel = computed(() => {
    const d = this.currentDate();
    switch (this.mode()) {
      case 'month':
        return `${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`;
      case 'week': {
        const start = this.weekStart(d);
        const end = addDays(start, 6);
        return `${start.getDate()} ${MONTH_NAMES[start.getMonth()]} – ${end.getDate()} ${MONTH_NAMES[end.getMonth()]} ${end.getFullYear()}`;
      }
      case 'agenda':
        return `Agenda – ${MONTH_NAMES[d.getMonth()]} ${d.getFullYear()}`;
    }
  });

  // ── Mapped events ────────────────────────────────────────────────────────
  private events = computed<CalendarEvent[]>(() => {
    const items = this.data() ?? [];
    const m = this.mapper();
    return items.map((item) => {
      const start = m.start(item);
      const rawEnd = m.end(item);
      const end = rawEnd ?? addDays(startOfDay(start), 1);
      return {
        item,
        title: m.title(item),
        start,
        end,
        color: m.color?.(item) ?? '#1976d2',
        allDay: m.allDay?.(item) ?? false,
        top: 0,
        height: 0,
        left: 0,
        width: 100,
      };
    });
  });

  // ── Month view ───────────────────────────────────────────────────────────
  monthDays = computed<MonthDay[]>(() => {
    const d = this.currentDate();
    const year = d.getFullYear();
    const month = d.getMonth();
    const firstDay = new Date(year, month, 1);
    const startOffset = firstDay.getDay(); // 0=Sun
    const start = addDays(firstDay, -startOffset);

    const days: MonthDay[] = [];
    for (let i = 0; i < 42; i++) {
      const date = addDays(start, i);
      days.push({
        date,
        isCurrentMonth: date.getMonth() === month,
        isToday: isSameDay(date, this.today),
        events: this.events().filter((e) => this.eventOnDay(e, date)),
      });
    }
    return days;
  });

  dayNames = DAY_NAMES;

  // ── Week view ────────────────────────────────────────────────────────────
  weekDays = computed<WeekDay[]>(() => {
    const start = this.weekStart(this.currentDate());
    return Array.from({ length: 7 }, (_, i) => {
      const date = addDays(start, i);
      const dayEvents = this.events()
        .filter((e) => !e.allDay && this.eventOnDay(e, date))
        .map((e) => ({ ...e }));
      this.layoutDayEvents(dayEvents, date);
      return { date, isToday: isSameDay(date, this.today), events: dayEvents };
    });
  });

  allDayWeekEvents = computed<{ event: CalendarEvent; colStart: number; colSpan: number }[]>(() => {
    const start = this.weekStart(this.currentDate());
    const result: { event: CalendarEvent; colStart: number; colSpan: number }[] = [];
    this.events()
      .filter((e) => e.allDay)
      .forEach((e) => {
        const colStart = Math.max(0, Math.round((startOfDay(e.start).getTime() - start.getTime()) / 86400000));
        const colEnd = Math.min(7, Math.round((startOfDay(e.end).getTime() - start.getTime()) / 86400000));
        if (colStart < 7 && colEnd > 0) {
          result.push({ event: e, colStart, colSpan: Math.max(1, colEnd - colStart) });
        }
      });
    return result;
  });

  nowTop = computed(() => {
    const now = new Date();
    return (now.getHours() * 60 + now.getMinutes()) * (HOUR_PX / 60);
  });

  // ── Agenda view ──────────────────────────────────────────────────────────
  agendaGroups = computed<AgendaGroup[]>(() => {
    const d = this.currentDate();
    const start = new Date(d.getFullYear(), d.getMonth(), 1);
    const end = new Date(d.getFullYear(), d.getMonth() + 1, 0);

    const groups = new Map<string, AgendaGroup>();
    this.events()
      .filter((e) => e.start <= end && e.end >= start)
      .sort((a, b) => a.start.getTime() - b.start.getTime())
      .forEach((e) => {
        const key = startOfDay(e.start).toISOString();
        if (!groups.has(key)) {
          const date = startOfDay(e.start);
          groups.set(key, {
            date,
            label: `${DAY_NAMES[date.getDay()]}, ${date.getDate()} de ${MONTH_NAMES[date.getMonth()]}`,
            events: [],
          });
        }
        groups.get(key)!.events.push(e);
      });

    return [...groups.values()];
  });

  constructor() {
    effect(() => {
      this.mode.set(this.initialMode());
    });
    effect(() => {
      const m = this.mode();
      const d = this.currentDate();
      this.emitPeriod(m, d);
    });
  }

  setMode(m: CalendarMode): void {
    this.mode.set(m);
  }

  navigate(dir: 1 | -1): void {
    const d = this.currentDate();
    switch (this.mode()) {
      case 'month':
        this.currentDate.set(new Date(d.getFullYear(), d.getMonth() + dir, 1));
        break;
      case 'week':
        this.currentDate.set(addDays(d, dir * 7));
        break;
      case 'agenda':
        this.currentDate.set(new Date(d.getFullYear(), d.getMonth() + dir, 1));
        break;
    }
  }

  goToToday(): void {
    this.currentDate.set(new Date());
  }

  pad(n: number): string {
    return n.toString().padStart(2, '0');
  }

  // ── Private helpers ──────────────────────────────────────────────────────
  private weekStart(d: Date): Date {
    const day = d.getDay();
    return addDays(startOfDay(d), -day);
  }

  private eventOnDay(e: CalendarEvent, day: Date): boolean {
    return startOfDay(e.start) <= day && startOfDay(e.end) > day;
  }

  private layoutDayEvents(events: CalendarEvent[], day: Date): void {
    events.forEach((e) => {
      const dayStart = startOfDay(day).getTime();
      const evStart = Math.max(e.start.getTime(), dayStart);
      const evEnd = Math.min(e.end.getTime(), dayStart + 86400000);
      const startMin = (evStart - dayStart) / 60000;
      const endMin = (evEnd - dayStart) / 60000;
      e.top = startMin * (HOUR_PX / 60);
      e.height = Math.max(30, (endMin - startMin) * (HOUR_PX / 60));
    });

    // Overlap layout: assign columns
    const groups: CalendarEvent[][] = [];
    for (const ev of events) {
      const grp = groups.find((g) => g.some((o) => overlaps(o, ev)));
      if (grp) {
        grp.push(ev);
      } else {
        groups.push([ev]);
      }
    }
    for (const grp of groups) {
      const cols: CalendarEvent[][] = [];
      for (const ev of grp) {
        const col = cols.find((c) => !c.some((o) => overlaps(o, ev)));
        if (col) {
          col.push(ev);
        } else {
          cols.push([ev]);
        }
      }
      const n = cols.length;
      cols.forEach((col, ci) =>
        col.forEach((ev) => {
          ev.left = (ci / n) * 100;
          ev.width = 100 / n;
        }),
      );
    }
  }

  private emitPeriod(mode: CalendarMode, d: Date): void {
    let from: Date, to: Date;
    switch (mode) {
      case 'month':
        from = new Date(d.getFullYear(), d.getMonth(), 1);
        to = new Date(d.getFullYear(), d.getMonth() + 1, 0);
        break;
      case 'week': {
        from = this.weekStart(d);
        to = addDays(from, 6);
        break;
      }
      default:
        from = new Date(d.getFullYear(), d.getMonth(), 1);
        to = new Date(d.getFullYear(), d.getMonth() + 1, 0);
    }
    this.periodChange.emit({ from, to });
  }
}
